-- Glossix: combined database update through app version 0.2.9.
-- Run this entire file once in Supabase SQL Editor, as the project owner.
-- Includes course content/progress/points/levels, friends and leaderboards,
-- preset profiles, username filtering/uniqueness, spoken-language preferences,
-- banners, all 50 level-earned backgrounds, private owner cosmetic grants,
-- security permissions and all 86 avatar IDs (including Kirin).
-- Rerunnable: existing accounts, points, progress and owner grants are retained.
-- App layout, animation and avatar image files ship with the app, not SQL.

-- Paste this entire script into your Glossix project's SQL Editor and Run.
-- Additive, rerunnable migration. No existing Auth users or learning data are deleted.
begin;
create schema if not exists glossix_private;
revoke all on schema glossix_private from public, anon, authenticated;
create table if not exists glossix_private.profiles (
 user_id uuid primary key references auth.users(id) on delete cascade,
 username text not null unique check (username ~ '^[a-z0-9_]{3,20}$'),
 display_name text not null check (length(display_name) between 1 and 40),
 global_visible boolean not null default false,
 created_at timestamptz not null default now()
);
create table if not exists glossix_private.friendships (
 low_id uuid not null references glossix_private.profiles(user_id) on delete cascade,
 high_id uuid not null references glossix_private.profiles(user_id) on delete cascade,
 requester uuid not null,
 status text not null check(status in ('pending','accepted')) default 'pending',
 created_at timestamptz not null default now(),
 primary key(low_id,high_id),check(low_id<high_id),check(requester in (low_id,high_id))
);
create table if not exists glossix_private.activities (activity text primary key);
create table if not exists glossix_private.points (
 user_id uuid not null references glossix_private.profiles(user_id) on delete cascade,
 activity text not null references glossix_private.activities(activity),
 earned_day date not null default (now() at time zone 'UTC')::date,
 points integer not null default 10 check(points=10),
 primary key(user_id,activity,earned_day)
);
create index if not exists glossix_points_day on glossix_private.points(earned_day,user_id);
create index if not exists glossix_friends_high on glossix_private.friendships(high_id,status);
alter table glossix_private.profiles enable row level security;
alter table glossix_private.friendships enable row level security;
alter table glossix_private.points enable row level security;
alter table glossix_private.activities enable row level security;
revoke all on all tables in schema glossix_private from public,anon,authenticated;

create or replace function public.glossix_profile(p_username text default null,p_display_name text default null,p_global_visible boolean default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid:=auth.uid(); r glossix_private.profiles%rowtype;
begin
 if u is null then raise exception 'Please sign in first'; end if;
 if p_username is not null then
  if lower(trim(p_username)) !~ '^[a-z0-9_]{3,20}$' then raise exception 'Username must be 3–20 letters, numbers or underscores'; end if;
  if length(trim(coalesce(p_display_name,''))) not between 1 and 40 then raise exception 'Display name must be 1–40 characters'; end if;
  begin
   insert into glossix_private.profiles(user_id,username,display_name,global_visible)
   values(u,lower(trim(p_username)),trim(p_display_name),coalesce(p_global_visible,false))
   on conflict(user_id) do update set username=excluded.username,display_name=excluded.display_name,global_visible=excluded.global_visible;
  exception when unique_violation then raise exception 'That username is already taken'; end;
 end if;
 select * into r from glossix_private.profiles where user_id=u;
 if not found then return null; end if;
 return jsonb_build_object('user_id',r.user_id,'username',r.username,'display_name',r.display_name,'global_visible',r.global_visible);
end $$;

create or replace function public.glossix_friend_action(p_action text,p_username text default null,p_user_id uuid default null)
returns void language plpgsql security definer set search_path = '' as $$
declare u uuid:=auth.uid(); t uuid; l uuid; h uuid; f glossix_private.friendships%rowtype;
begin
 if u is null then raise exception 'Please sign in first'; end if;
 -- Lock caller's profile to serialize requests and enforce limits.
 perform 1 from glossix_private.profiles where user_id=u for update;
 if not found then raise exception 'Choose your username first'; end if;
 if p_action='request' then
  select user_id into t from glossix_private.profiles where username=lower(trim(p_username));
  if t is null then raise exception 'No learner has that username'; end if;
 else t:=p_user_id; end if;
 if t is null or t=u then raise exception 'Choose another learner'; end if;
 l:=least(u,t);h:=greatest(u,t);
 select * into f from glossix_private.friendships where low_id=l and high_id=h for update;
 if p_action='request' then
  if f.low_id is not null then raise exception 'You already have a friendship or pending request with this learner'; end if;
  if (select count(*) from glossix_private.friendships where requester=u and status='pending')>=30 then raise exception 'You can have up to 30 outgoing requests'; end if;
  insert into glossix_private.friendships(low_id,high_id,requester) values(l,h,u);
 elsif p_action='accept' then
  if f.low_id is null or f.status<>'pending' or f.requester=u then raise exception 'Only the recipient can accept this request'; end if;
  if (select count(*) from glossix_private.friendships where status='accepted' and (low_id=u or high_id=u))>=200 or (select count(*) from glossix_private.friendships where status='accepted' and (low_id=t or high_id=t))>=200 then raise exception 'Friend limit reached'; end if;
  update glossix_private.friendships set status='accepted' where low_id=l and high_id=h;
 elsif p_action='decline' then
  if f.low_id is null or f.status<>'pending' or f.requester=u then raise exception 'Only the recipient can decline this request'; end if;
  delete from glossix_private.friendships where low_id=l and high_id=h;
 elsif p_action='cancel' then
  if f.low_id is null or f.status<>'pending' or f.requester<>u then raise exception 'Only the sender can cancel this request'; end if;
  delete from glossix_private.friendships where low_id=l and high_id=h;
 elsif p_action='remove' then
  if f.low_id is null or f.status<>'accepted' then raise exception 'Friendship not found'; end if;
  delete from glossix_private.friendships where low_id=l and high_id=h;
 else raise exception 'Unknown friend action'; end if;
end $$;

create or replace function public.glossix_friends()
returns table(user_id uuid,username text,display_name text,relationship text)
language plpgsql security definer set search_path = '' as $$
begin
 if auth.uid() is null then raise exception 'Please sign in first'; end if;
 return query select p.user_id,p.username,p.display_name,
 case when f.status='accepted' then 'friend' when f.requester=auth.uid() then 'outgoing' else 'incoming' end
 from glossix_private.friendships f join glossix_private.profiles p on p.user_id=case when f.low_id=auth.uid() then f.high_id else f.low_id end
 where f.low_id=auth.uid() or f.high_id=auth.uid() order by p.username;
end $$;

create or replace function public.glossix_award(p_activity text,p_undo boolean default false)
returns integer language plpgsql security definer set search_path = '' as $$
declare u uuid:=auth.uid(); d date:=(now() at time zone 'UTC')::date; awarded integer;
begin
 if u is null then raise exception 'Please sign in first'; end if;
 perform 1 from glossix_private.profiles where user_id=u for update;
 if not found then return 0; end if;
 if not exists(select 1 from glossix_private.activities where activity=p_activity) then return 0; end if;
 if p_undo then
  if p_activity not like 'alphabet:%' then raise exception 'Only letter practice can be undone'; end if;
  delete from glossix_private.points where user_id=u and activity=p_activity and earned_day=d;
  return 0;
 end if;
 if (select count(*) from glossix_private.points where user_id=u and earned_day=d)>=50 then return 0; end if;
 insert into glossix_private.points(user_id,activity,earned_day) values(u,p_activity,d) on conflict do nothing;
 get diagnostics awarded=row_count;
 return awarded*10;
end $$;

create or replace function public.glossix_leaderboard(p_scope text default 'global',p_period text default 'weekly')
returns table(rank_position bigint,user_id uuid,username text,display_name text,points bigint,is_you boolean)
language plpgsql security definer set search_path = '' as $$
begin
 if auth.uid() is null then raise exception 'Please sign in first'; end if;
 if p_scope not in ('global','friends') or p_period not in ('weekly','alltime') then raise exception 'Invalid leaderboard filter'; end if;
 return query with totals as (
 select p.user_id,p.username,p.display_name,coalesce(sum(s.points),0)::bigint as score
 from glossix_private.profiles p left join glossix_private.points s on s.user_id=p.user_id
 and (p_period='alltime' or s.earned_day>=date_trunc('week',now() at time zone 'UTC')::date)
 where (p_scope='global' and p.global_visible) or (p_scope='friends' and (p.user_id=auth.uid() or exists(
 select 1 from glossix_private.friendships f where f.status='accepted' and f.low_id=least(auth.uid(),p.user_id) and f.high_id=greatest(auth.uid(),p.user_id))))
 group by p.user_id,p.username,p.display_name
 ), ranked as (select rank() over(order by totals.score desc) as place,totals.*,row_number() over(order by totals.score desc,totals.username) as rownum from totals)
 select r.place,r.user_id,r.username,r.display_name,r.score,r.user_id=auth.uid() from ranked r
 where r.rownum<=100 or r.user_id=auth.uid() order by r.score desc,r.username;
end $$;

revoke all on function public.glossix_profile(text,text,boolean) from public,anon,authenticated;
revoke all on function public.glossix_friend_action(text,text,uuid) from public,anon,authenticated;
revoke all on function public.glossix_friends() from public,anon,authenticated;
revoke all on function public.glossix_award(text,boolean) from public,anon,authenticated;
revoke all on function public.glossix_leaderboard(text,text) from public,anon,authenticated;
grant execute on function public.glossix_profile(text,text,boolean),public.glossix_friend_action(text,text,uuid),public.glossix_friends(),public.glossix_award(text,boolean),public.glossix_leaderboard(text,text) to authenticated;
