-- BEGIN PROGRESSIVE COURSE UPDATE
-- Progressive Russian course and account levels. Run after SUPABASE-SOCIAL.sql.
-- Existing accounts, friends and points are preserved. No learning or user rows are deleted.
begin;
alter table glossix_private.points drop constraint if exists points_points_check;
alter table glossix_private.points drop constraint if exists glossix_positive_points;
alter table glossix_private.points add constraint glossix_positive_points check(points>0);
create table if not exists glossix_private.learning_items(id text primary key,lesson integer not null,answer text not null);
create table if not exists glossix_private.learning_accounts(user_id uuid primary key references glossix_private.profiles(user_id) on delete cascade,unlocked integer not null default 0);
create table if not exists glossix_private.learning_progress(user_id uuid not null references glossix_private.profiles(user_id) on delete cascade,item_id text not null references glossix_private.learning_items(id),successes integer not null default 0,last_success timestamptz,due timestamptz not null default now(),interval_days integer not null default 0,attempts integer not null default 0,mistakes integer not null default 0,primary key(user_id,item_id));
create table if not exists glossix_private.learning_daily(user_id uuid not null references glossix_private.profiles(user_id) on delete cascade,day date not null,attempts integer not null default 0,correct integer not null default 0,primary key(user_id,day));
create table if not exists glossix_private.learning_recalls(user_id uuid not null references glossix_private.profiles(user_id) on delete cascade,item_id text not null references glossix_private.learning_items(id),day date not null,spaced boolean not null default false,primary key(user_id,item_id,day));
alter table glossix_private.learning_items enable row level security;
alter table glossix_private.learning_accounts enable row level security;
alter table glossix_private.learning_progress enable row level security;
alter table glossix_private.learning_daily enable row level security;
alter table glossix_private.learning_recalls enable row level security;
revoke all on all tables in schema glossix_private from public,anon,authenticated;
create or replace function glossix_private.clean_answer(value text) returns text language sql immutable set search_path='' as $$select trim(regexp_replace(regexp_replace(replace(replace(lower(value),'ё','е'),U&'\0301',''),'[.!?,]','','g'),'\s+',' ','g'))$$;
create or replace function glossix_private.credit(u uuid,a text,n integer,once_ever boolean default false) returns integer language plpgsql set search_path='' as $$declare count_awarded integer;begin if once_ever and exists(select 1 from glossix_private.points where user_id=u and activity=a) then return 0;end if;insert into glossix_private.points(user_id,activity,points) values(u,a,n) on conflict do nothing;get diagnostics count_awarded=row_count;return count_awarded*n;end$$;
create or replace function public.glossix_level(p_points numeric) returns text language sql immutable set search_path='' as $$select greatest(1,floor((1+sqrt(1+8*greatest(p_points,0)/100))/2))::text$$;
create or replace function public.glossix_learning_state() returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();d date:=(now() at time zone 'UTC')::date;score numeric;progress jsonb;daily jsonb;unlocked_lesson integer;done jsonb;
begin
 if u is null then raise exception 'Please sign in first';end if;
 if not exists(select 1 from glossix_private.profiles where user_id=u) then return jsonb_build_object('profileRequired',true,'points','0','unlocked',0,'items','{}'::jsonb,'daily','{}'::jsonb,'completedLessons','[]'::jsonb);end if;
 insert into glossix_private.learning_accounts(user_id) values(u) on conflict do nothing;
 select unlocked into unlocked_lesson from glossix_private.learning_accounts where user_id=u;
 select coalesce(sum(points),0) into score from glossix_private.points where user_id=u;
 select coalesce(jsonb_object_agg(item_id,jsonb_build_object('successes',successes,'lastSuccess',case when last_success is null then null else floor(extract(epoch from last_success)*1000) end,'due',floor(extract(epoch from due)*1000),'interval',interval_days,'attempts',attempts,'mistakes',mistakes)),'{}'::jsonb) into progress from glossix_private.learning_progress where user_id=u;
 select jsonb_build_object('attempts',coalesce((select attempts from glossix_private.learning_daily where user_id=u and day=d),0),'correct',coalesce((select correct from glossix_private.learning_daily where user_id=u and day=d),0),'successIds',coalesce((select jsonb_agg(item_id) from glossix_private.learning_recalls where user_id=u and day=d),'[]'::jsonb),'spacedIds',coalesce((select jsonb_agg(item_id) from glossix_private.learning_recalls where user_id=u and day=d and spaced),'[]'::jsonb),'challenges',coalesce((select jsonb_agg(substr(activity,11)) from glossix_private.points where user_id=u and earned_day=d and activity like 'challenge:%'),'[]'::jsonb)) into daily;
 select coalesce(jsonb_agg(substr(activity,8)),'[]'::jsonb) into done from glossix_private.points where user_id=u and activity like 'lesson:%';
 return jsonb_build_object('curriculumLessons',(select coalesce(max(lesson)+1,0) from glossix_private.learning_items),'points',score::text,'level',public.glossix_level(score),'unlocked',unlocked_lesson,'items',progress,'daily',jsonb_build_object(d::text,daily),'completedLessons',done,'awards','{}'::jsonb);
end$$;
create or replace function public.glossix_learning_answer(p_item text,p_answer text,p_assisted boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();d date:=(now() at time zone 'UTC')::date;i glossix_private.learning_items%rowtype;p glossix_private.learning_progress%rowtype;correct_answer boolean;spaced_review boolean;earned integer:=0;unlocked_lesson integer;n integer;review_n integer;attempt_n integer;correct_n integer;lesson_id text;
begin
 if u is null then raise exception 'Please sign in first';end if;
 perform 1 from glossix_private.profiles where user_id=u for update;if not found then raise exception 'Choose your username first';end if;
 insert into glossix_private.learning_accounts(user_id) values(u) on conflict do nothing;
 select unlocked into unlocked_lesson from glossix_private.learning_accounts where user_id=u;
 select * into i from glossix_private.learning_items where id=p_item;if not found or i.lesson>unlocked_lesson then raise exception 'This lesson is locked';end if;
 if length(p_answer)>400 then raise exception 'Answer is too long';end if;
 correct_answer:=glossix_private.clean_answer(p_answer)=glossix_private.clean_answer(i.answer);
 if p_assisted then return jsonb_build_object('correct',correct_answer,'assisted',true,'earned',0,'state',public.glossix_learning_state());end if;
 insert into glossix_private.learning_daily(user_id,day,attempts,correct) values(u,d,1,case when correct_answer then 1 else 0 end) on conflict(user_id,day) do update set attempts=glossix_private.learning_daily.attempts+1,correct=glossix_private.learning_daily.correct+case when correct_answer then 1 else 0 end;
 insert into glossix_private.learning_progress(user_id,item_id) values(u,p_item) on conflict do nothing;
 select * into p from glossix_private.learning_progress where user_id=u and item_id=p_item;
 if correct_answer then
  spaced_review:=p.last_success is not null and (p.last_success at time zone 'UTC')::date<>d and now()-p.last_success>=interval '20 hours';
  if p.last_success is null or spaced_review then p.successes:=p.successes+1;p.interval_days:=case when p.successes<2 then 1 else least(30,power(2,least(p.successes-1,5))::integer) end;p.last_success:=now();p.due:=now()+make_interval(days=>p.interval_days);end if;
  update glossix_private.learning_progress set successes=p.successes,last_success=p.last_success,due=p.due,interval_days=p.interval_days,attempts=attempts+1 where user_id=u and item_id=p_item;
  insert into glossix_private.learning_recalls(user_id,item_id,day,spaced) values(u,p_item,d,spaced_review) on conflict(user_id,item_id,day) do update set spaced=glossix_private.learning_recalls.spaced or excluded.spaced;
  earned:=earned+glossix_private.credit(u,'learning-recall:'||p_item,5);
  lesson_id:='ru-l'||lpad((i.lesson+1)::text,greatest(2,length((i.lesson+1)::text)),'0');
  if not exists(select 1 from glossix_private.learning_items x left join glossix_private.learning_progress r on r.user_id=u and r.item_id=x.id where x.lesson=i.lesson and coalesce(r.successes,0)<1) then earned:=earned+glossix_private.credit(u,'lesson:'||lesson_id,50,true);end if;
  if i.lesson=unlocked_lesson and not exists(select 1 from glossix_private.learning_items x left join glossix_private.learning_progress r on r.user_id=u and r.item_id=x.id where x.lesson=i.lesson and coalesce(r.successes,0)<2) then update glossix_private.learning_accounts set unlocked=unlocked+1 where user_id=u;end if;
 else update glossix_private.learning_progress set successes=0,last_success=null,due=now()+interval '10 minutes',interval_days=0,attempts=attempts+1,mistakes=mistakes+1 where user_id=u and item_id=p_item;end if;
 select count(*),count(*) filter(where learning_recalls.spaced) into n,review_n from glossix_private.learning_recalls where user_id=u and day=d;
 select attempts,correct into attempt_n,correct_n from glossix_private.learning_daily where user_id=u and day=d;
 if n>=5 then earned:=earned+glossix_private.credit(u,'daily-practice',20);end if;
 if n>=10 then earned:=earned+glossix_private.credit(u,'challenge:vocabulary',25);end if;
 if n>=5 and correct_n::bigint*100>=attempt_n::bigint*80 then earned:=earned+glossix_private.credit(u,'challenge:accuracy',25);end if;
 if review_n>=5 then earned:=earned+glossix_private.credit(u,'challenge:memory',25);end if;
 return jsonb_build_object('correct',correct_answer,'assisted',false,'earned',earned,'state',public.glossix_learning_state());
end$$;
-- Remove the previous daily cap while retaining once-per-activity-per-day deduplication.
create or replace function public.glossix_award(p_activity text,p_undo boolean default false) returns integer language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();d date:=(now() at time zone 'UTC')::date;
begin
 if u is null then raise exception 'Please sign in first';end if;
 perform 1 from glossix_private.profiles where user_id=u for update;if not found then return 0;end if;
 -- Course recall, lesson and challenge bonuses must pass through checked answers.
 if p_activity like 'learning-recall:%' or p_activity like 'lesson:%' or p_activity like 'challenge:%' or p_activity='daily-practice' then raise exception 'Complete the course exercise to earn these points';end if;
 if not exists(select 1 from glossix_private.activities where activity=p_activity) then return 0;end if;
 if p_undo then if p_activity not like 'alphabet:%' then raise exception 'Only letter practice can be undone';end if;delete from glossix_private.points where user_id=u and activity=p_activity and earned_day=d;return 0;end if;
 return glossix_private.credit(u,p_activity,10);
end$$;
create or replace function public.glossix_leaderboard_levels(p_scope text default 'global',p_period text default 'weekly') returns table(rank_position bigint,user_id uuid,username text,display_name text,points text,is_you boolean,account_level text) language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null then raise exception 'Please sign in first';end if;
 if p_scope not in ('global','friends') or p_period not in ('weekly','alltime') then raise exception 'Invalid leaderboard filter';end if;
 return query with totals as(select p.user_id,p.username,p.display_name,coalesce(sum(s.points) filter(where p_period='alltime' or s.earned_day>=date_trunc('week',now() at time zone 'UTC')::date),0) as score,coalesce(sum(s.points),0) as lifetime from glossix_private.profiles p left join glossix_private.points s on s.user_id=p.user_id where (p_scope='global' and p.global_visible) or (p_scope='friends' and (p.user_id=auth.uid() or exists(select 1 from glossix_private.friendships f where f.status='accepted' and f.low_id=least(auth.uid(),p.user_id) and f.high_id=greatest(auth.uid(),p.user_id)))) group by p.user_id,p.username,p.display_name),ranked as(select rank() over(order by totals.score desc) as place,totals.*,row_number() over(order by totals.score desc,totals.username) as rownum from totals) select r.place,r.user_id,r.username,r.display_name,r.score::text,r.user_id=auth.uid(),public.glossix_level(r.lifetime) from ranked r where r.rownum<=100 or r.user_id=auth.uid() order by r.score desc,r.username;
end$$;
revoke all on function glossix_private.clean_answer(text),glossix_private.credit(uuid,text,integer,boolean) from public,anon,authenticated;
revoke all on function public.glossix_level(numeric),public.glossix_learning_state(),public.glossix_learning_answer(text,text,boolean),public.glossix_leaderboard_levels(text,text) from public,anon,authenticated;
grant execute on function public.glossix_level(numeric),public.glossix_learning_state(),public.glossix_learning_answer(text,text,boolean),public.glossix_leaderboard_levels(text,text) to authenticated;
