-- BEGIN ITALIAN AND LANGUAGE UPDATE
-- Italian course and multiple learning languages. Run after SUPABASE-LONG-COURSE.sql.
-- Preserves Russian progress, accounts, friendships and points. Rerunnable.
-- Daily bonuses are shared across languages; memory and lesson unlocks are separate.
begin;
alter table glossix_private.learning_items add column if not exists language text not null default 'ru';
alter table glossix_private.learning_accounts add column if not exists language text not null default 'ru';
alter table glossix_private.learning_accounts drop constraint if exists learning_accounts_pkey;
alter table glossix_private.learning_accounts add primary key(user_id,language);
alter table glossix_private.profiles add column if not exists active_languages text[] not null default array['ru'];
alter table glossix_private.profiles alter column active_languages set default '{}';
alter table glossix_private.profiles add column if not exists recent_language text default 'ru';
alter table glossix_private.profiles alter column recent_language drop default;
create or replace function glossix_private.learning_language_touch(u uuid,code text) returns void language sql set search_path='' as $$
 update glossix_private.profiles set active_languages=case when code=any(active_languages) then active_languages else array_append(active_languages,code) end,recent_language=code where user_id=u and code in ('ru','it');
$$;
create or replace function glossix_private.clean_answer(value text) returns text language sql immutable set search_path='' as $$select trim(regexp_replace(regexp_replace(replace(replace(replace(replace(lower(normalize(value,NFC)),'ё','е'),U&'\0301',''),'’',chr(39)),'‘',chr(39)),'[.!?,]','','g'),'\s+',' ','g'))$$;
create or replace function public.glossix_profile(p_username text default null,p_display_name text default null,p_global_visible boolean default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid:=auth.uid(); r glossix_private.profiles%rowtype;
begin
 if u is null then raise exception 'Please sign in first'; end if;
 if p_username is not null then
  if lower(trim(p_username)) !~ '^[a-z0-9_]{3,20}$' then raise exception 'Username must be 3–20 letters, numbers or underscores'; end if;
  if length(trim(coalesce(p_display_name,''))) not between 1 and 40 then raise exception 'Display name must be 1–40 characters'; end if;
  begin
   insert into glossix_private.profiles(user_id,username,display_name,global_visible)
   values(u,lower(trim(p_username)),trim(p_display_name),coalesce(p_global_visible,false))
   on conflict(user_id) do update set username=excluded.username,display_name=excluded.display_name,global_visible=excluded.global_visible;
  exception when unique_violation then raise exception 'That username is already taken'; end;
 end if;
 select * into r from glossix_private.profiles where user_id=u;
 if not found then return null; end if;
 return jsonb_build_object('user_id',r.user_id,'username',r.username,'display_name',r.display_name,'global_visible',r.global_visible,'active_languages',r.active_languages,'recent_language',r.recent_language);
end $$;


create or replace function public.glossix_language_set(p_language text,p_active boolean default true) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();p glossix_private.profiles%rowtype;langs text[];
begin
 if u is null then raise exception 'Please sign in first';end if;
 if p_language not in ('ru','it') or p_language is null or p_active is null then raise exception 'Unsupported language';end if;
 select * into p from glossix_private.profiles where user_id=u for update;if not found then raise exception 'Choose your username first';end if;
 langs:=case when p_active then case when p_language=any(p.active_languages) then p.active_languages else array_append(p.active_languages,p_language) end else array_remove(p.active_languages,p_language) end;
 update glossix_private.profiles set active_languages=langs,recent_language=case when p.recent_language=any(langs) then p.recent_language else langs[1] end where user_id=u;
 return public.glossix_profile();
end$$;
create or replace function public.glossix_course_state(p_language text) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();d date:=(now() at time zone 'UTC')::date;score numeric;progress jsonb;daily jsonb;unlocked_lesson integer;done jsonb;
begin
 if p_language not in ('ru','it') or p_language is null then raise exception 'Unsupported language';end if;
 if u is null then raise exception 'Please sign in first';end if;
 if not exists(select 1 from glossix_private.profiles where user_id=u) then return jsonb_build_object('profileRequired',true,'points','0','unlocked',0,'items','{}'::jsonb,'daily','{}'::jsonb,'completedLessons','[]'::jsonb);end if;
 insert into glossix_private.learning_accounts(user_id,language) values(u,p_language) on conflict do nothing;
 select unlocked into unlocked_lesson from glossix_private.learning_accounts where user_id=u and language=p_language;
 select coalesce(sum(points),0) into score from glossix_private.points where user_id=u;
 select coalesce(jsonb_object_agg(item_id,jsonb_build_object('successes',successes,'lastSuccess',case when last_success is null then null else floor(extract(epoch from last_success)*1000) end,'due',floor(extract(epoch from due)*1000),'interval',interval_days,'attempts',attempts,'mistakes',mistakes)),'{}'::jsonb) into progress from glossix_private.learning_progress where user_id=u;
 select jsonb_build_object('attempts',coalesce((select attempts from glossix_private.learning_daily where user_id=u and day=d),0),'correct',coalesce((select correct from glossix_private.learning_daily where user_id=u and day=d),0),'successIds',coalesce((select jsonb_agg(item_id) from glossix_private.learning_recalls where user_id=u and day=d),'[]'::jsonb),'spacedIds',coalesce((select jsonb_agg(item_id) from glossix_private.learning_recalls where user_id=u and day=d and spaced),'[]'::jsonb),'challenges',coalesce((select jsonb_agg(substr(activity,11)) from glossix_private.points where user_id=u and earned_day=d and activity like 'challenge:%'),'[]'::jsonb)) into daily;
 select coalesce(jsonb_agg(substr(activity,8)),'[]'::jsonb) into done from glossix_private.points where user_id=u and activity like 'lesson:%';
 return jsonb_build_object('curriculumLessons',(select coalesce(max(lesson)+1,0) from glossix_private.learning_items where language=p_language),'points',score::text,'level',public.glossix_level(score),'unlocked',unlocked_lesson,'items',progress,'daily',jsonb_build_object(d::text,daily),'completedLessons',done,'awards','{}'::jsonb);
end$$;

create or replace function public.glossix_course_answer(p_language text,p_item text,p_answer text,p_assisted boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();d date:=(now() at time zone 'UTC')::date;i glossix_private.learning_items%rowtype;p glossix_private.learning_progress%rowtype;correct_answer boolean;spaced_review boolean;earned integer:=0;unlocked_lesson integer;n integer;review_n integer;attempt_n integer;correct_n integer;lesson_id text;
begin
 if p_language not in ('ru','it') or p_language is null then raise exception 'Unsupported language';end if;
 if u is null then raise exception 'Please sign in first';end if;
 perform 1 from glossix_private.profiles where user_id=u for update;if not found then raise exception 'Choose your username first';end if;
 insert into glossix_private.learning_accounts(user_id,language) values(u,p_language) on conflict do nothing;
 select unlocked into unlocked_lesson from glossix_private.learning_accounts where user_id=u and language=p_language;
 select * into i from glossix_private.learning_items where id=p_item and language=p_language;if not found or i.lesson>unlocked_lesson then raise exception 'This lesson is locked';end if;
 if length(p_answer)>400 then raise exception 'Answer is too long';end if;
 correct_answer:=glossix_private.clean_answer(p_answer)=glossix_private.clean_answer(i.answer);
 if p_assisted then return jsonb_build_object('correct',correct_answer,'assisted',true,'earned',0,'state',public.glossix_course_state(p_language));end if;
 insert into glossix_private.learning_daily(user_id,day,attempts,correct) values(u,d,1,case when correct_answer then 1 else 0 end) on conflict(user_id,day) do update set attempts=glossix_private.learning_daily.attempts+1,correct=glossix_private.learning_daily.correct+case when correct_answer then 1 else 0 end;
 insert into glossix_private.learning_progress(user_id,item_id) values(u,p_item) on conflict do nothing;
 select * into p from glossix_private.learning_progress where user_id=u and item_id=p_item;
 if correct_answer then
  perform glossix_private.learning_language_touch(u,p_language);
  spaced_review:=p.last_success is not null and (p.last_success at time zone 'UTC')::date<>d and now()-p.last_success>=interval '20 hours';
  if p.last_success is null or spaced_review then p.successes:=p.successes+1;p.interval_days:=case when p.successes<2 then 1 else least(30,power(2,least(p.successes-1,5))::integer) end;p.last_success:=now();p.due:=now()+make_interval(days=>p.interval_days);end if;
  update glossix_private.learning_progress set successes=p.successes,last_success=p.last_success,due=p.due,interval_days=p.interval_days,attempts=attempts+1 where user_id=u and item_id=p_item;
  insert into glossix_private.learning_recalls(user_id,item_id,day,spaced) values(u,p_item,d,spaced_review) on conflict(user_id,item_id,day) do update set spaced=glossix_private.learning_recalls.spaced or excluded.spaced;
  earned:=earned+glossix_private.credit(u,'learning-recall:'||p_item,5);
  lesson_id:=p_language||'-l'||lpad((i.lesson+1)::text,greatest(2,length((i.lesson+1)::text)),'0');
  if not exists(select 1 from glossix_private.learning_items x left join glossix_private.learning_progress r on r.user_id=u and r.item_id=x.id where x.language=p_language and x.lesson=i.lesson and coalesce(r.successes,0)<1) then earned:=earned+glossix_private.credit(u,'lesson:'||lesson_id,50,true);end if;
  if i.lesson=unlocked_lesson and not exists(select 1 from glossix_private.learning_items x left join glossix_private.learning_progress r on r.user_id=u and r.item_id=x.id where x.language=p_language and x.lesson=i.lesson and coalesce(r.successes,0)<2) then update glossix_private.learning_accounts set unlocked=unlocked+1 where user_id=u and language=p_language;end if;
 else update glossix_private.learning_progress set successes=0,last_success=null,due=now()+interval '10 minutes',interval_days=0,attempts=attempts+1,mistakes=mistakes+1 where user_id=u and item_id=p_item;end if;
 select count(*),count(*) filter(where learning_recalls.spaced) into n,review_n from glossix_private.learning_recalls where user_id=u and day=d;
 select attempts,correct into attempt_n,correct_n from glossix_private.learning_daily where user_id=u and day=d;
 if n>=5 then earned:=earned+glossix_private.credit(u,'daily-practice',20);end if;
 if n>=10 then earned:=earned+glossix_private.credit(u,'challenge:vocabulary',25);end if;
 if n>=5 and correct_n::bigint*100>=attempt_n::bigint*80 then earned:=earned+glossix_private.credit(u,'challenge:accuracy',25);end if;
 if review_n>=5 then earned:=earned+glossix_private.credit(u,'challenge:memory',25);end if;
 return jsonb_build_object('correct',correct_answer,'assisted',false,'earned',earned,'state',public.glossix_course_state(p_language));
end$$;

-- Older clients keep their Russian-only contract.
create or replace function public.glossix_learning_state() returns jsonb language sql security definer set search_path='' as $$select public.glossix_course_state('ru')$$;
create or replace function public.glossix_learning_answer(p_item text,p_answer text,p_assisted boolean default false) returns jsonb language sql security definer set search_path='' as $$select public.glossix_course_answer('ru',p_item,p_answer,p_assisted)$$;
create or replace function public.glossix_award(p_activity text,p_undo boolean default false) returns integer language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();d date:=(now() at time zone 'UTC')::date;
begin
 if u is null then raise exception 'Please sign in first';end if;
 perform 1 from glossix_private.profiles where user_id=u for update;if not found then return 0;end if;
 -- Course recall, lesson and challenge bonuses must pass through checked answers.
 if p_activity like 'learning-recall:%' or p_activity like 'lesson:%' or p_activity like 'challenge:%' or p_activity='daily-practice' then raise exception 'Complete the course exercise to earn these points';end if;
 if not exists(select 1 from glossix_private.activities where activity=p_activity) then return 0;end if;
 if p_undo then if p_activity not like 'alphabet:%' then raise exception 'Only letter practice can be undone';end if;delete from glossix_private.points where user_id=u and activity=p_activity and earned_day=d;return 0;end if;
 perform glossix_private.learning_language_touch(u,case when p_activity like 'cards:it-%' or p_activity like 'spelling:it-%' or p_activity like '%:it:%' then 'it' else 'ru' end);
 return glossix_private.credit(u,p_activity,10);
end$$;

create or replace function public.glossix_leaderboard_languages(p_scope text default 'global',p_period text default 'weekly') returns jsonb language sql security definer set search_path='' as $$
 select coalesce(jsonb_agg(to_jsonb(b)||jsonb_build_object('active_languages',p.active_languages,'recent_language',p.recent_language) order by b.rank_position,b.username),'[]'::jsonb) from public.glossix_leaderboard_levels(p_scope,p_period) b join glossix_private.profiles p on p.user_id=b.user_id;
$$;
create or replace function public.glossix_friends_languages() returns jsonb language sql security definer set search_path='' as $$
 select coalesce(jsonb_agg(to_jsonb(f)||jsonb_build_object('active_languages',p.active_languages,'recent_language',p.recent_language) order by f.username),'[]'::jsonb) from public.glossix_friends() f join glossix_private.profiles p on p.user_id=f.user_id;
$$;
revoke all on function glossix_private.learning_language_touch(uuid,text),glossix_private.clean_answer(text) from public,anon,authenticated;
revoke all on function public.glossix_language_set(text,boolean),public.glossix_course_state(text),public.glossix_course_answer(text,text,text,boolean),public.glossix_leaderboard_languages(text,text),public.glossix_friends_languages() from public,anon,authenticated;
grant execute on function public.glossix_language_set(text,boolean),public.glossix_course_state(text),public.glossix_course_answer(text,text,text,boolean),public.glossix_leaderboard_languages(text,text),public.glossix_friends_languages() to authenticated;
