-- BEGIN AVATAR UPDATE
-- Thirty selectable profile avatars. Run after the Italian / language update.
-- Existing users, language flags, points and progress are preserved. Rerunnable.
begin;
alter table glossix_private.profiles add column if not exists avatar_id text not null default 'fox';
create or replace function public.glossix_profile(p_username text default null,p_display_name text default null,p_global_visible boolean default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid:=auth.uid(); r glossix_private.profiles%rowtype;
begin
 if u is null then raise exception 'Please sign in first'; end if;
 if p_username is not null then
  if lower(trim(p_username)) !~ '^[a-z0-9_]{3,20}$' then raise exception 'Username must be 3–20 letters, numbers or underscores'; end if;
  if length(trim(coalesce(p_display_name,''))) not between 1 and 40 then raise exception 'Display name must be 1–40 characters'; end if;
  begin
   insert into glossix_private.profiles(user_id,username,display_name,global_visible)
   values(u,lower(trim(p_username)),trim(p_display_name),coalesce(p_global_visible,false))
   on conflict(user_id) do update set username=excluded.username,display_name=excluded.display_name,global_visible=excluded.global_visible;
  exception when unique_violation then raise exception 'That username is already taken'; end;
 end if;
 select * into r from glossix_private.profiles where user_id=u;
 if not found then return null; end if;
 return jsonb_build_object('user_id',r.user_id,'username',r.username,'display_name',r.display_name,'global_visible',r.global_visible,'active_languages',r.active_languages,'recent_language',r.recent_language,'avatar_id',r.avatar_id);
end $$;



create or replace function public.glossix_avatar_set(p_avatar text) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null then raise exception 'Please sign in first';end if;
 if p_avatar is null or p_avatar not in ('fox','cat','dog','owl','panda','lion','penguin','turtle','rabbit','frog','shark','butterfly','trex','triceratops','stegosaurus','brontosaurus','pterodactyl','raptor','dragon','unicorn','phoenix','kraken','griffin','pegasus','flag-ru','flag-it','flag-gb','flag-fr','flag-jp','flag-br') then raise exception 'Choose an available avatar';end if;
 update glossix_private.profiles set avatar_id=p_avatar where user_id=auth.uid();if not found then raise exception 'Choose your username in Friends first';end if;
 return public.glossix_profile();
end$$;
create or replace function public.glossix_leaderboard_languages(p_scope text default 'global',p_period text default 'weekly') returns jsonb language sql security definer set search_path='' as $$
 select coalesce(jsonb_agg(to_jsonb(b)||jsonb_build_object('active_languages',p.active_languages,'recent_language',p.recent_language,'avatar_id',p.avatar_id) order by b.rank_position,b.username),'[]'::jsonb) from public.glossix_leaderboard_levels(p_scope,p_period) b join glossix_private.profiles p on p.user_id=b.user_id;
$$;
create or replace function public.glossix_friends_languages() returns jsonb language sql security definer set search_path='' as $$
 select coalesce(jsonb_agg(to_jsonb(f)||jsonb_build_object('active_languages',p.active_languages,'recent_language',p.recent_language,'avatar_id',p.avatar_id) order by f.username),'[]'::jsonb) from public.glossix_friends() f join glossix_private.profiles p on p.user_id=f.user_id;
$$;
revoke all on function public.glossix_avatar_set(text) from public,anon,authenticated;
grant execute on function public.glossix_avatar_set(text) to authenticated;
commit;

-- BEGIN PRESET PROFILE UPDATE
-- Profile presets and username filtering. Run after the full social setup.
-- Existing accounts, avatars, points and language progress are retained.
begin;
alter table glossix_private.profiles add column if not exists region_id text not null default '';
alter table glossix_private.profiles add column if not exists hobbies text[] not null default '{}';
create or replace function glossix_private.username_allowed(p_name text) returns boolean language plpgsql immutable set search_path='' as $$
declare n text:=lower(trim(p_name)); f text; compact text; w text;
begin
 if n is null or n !~ '^[a-z0-9_]{3,20}$' then return false;end if;
 foreach f in array array[translate(n,'01345789','oieastbg'),translate(n,'01345789','oleastbg')] loop
  compact:=regexp_replace(replace(f,'_',''),'(.)\1+','\1','g');
  foreach w in array array['fuck','shit','bitch','cunt','asshole','arsehole','dickhead','wanker','motherfucker','nigger','nigga','faggot','faggy','slut','whore','porn','nazi','hitler','rape','rapist','pedo','retard','dumbass','bastard','piss','twat','bollock','douche','suicide','killyourself','killurself','idiot','stupid','loser','screwyou','suckmy','sex','merda','cazzo','vaffanculo','stronzo','puttana','suka','blyat','bljat','khuy','pizda']::text[] loop if position(regexp_replace(w,'(.)\1+','\1','g') in compact)>0 then return false;end if;end loop;
  foreach w in array array['ass','arse','cock','dick','fag','kys','wtf','stfu']::text[] loop if compact=regexp_replace(w,'(.)\1+','\1','g') or w=any(string_to_array(n,'_')) then return false;end if;end loop;
 end loop;
 return true;
end$$;
-- Retire old free-text display names and neutralise existing blocked usernames.
-- Use a collision-checked neutral name; never delete an account or its progress.
do $$declare r record;n text;attempt integer;begin
 for r in select user_id from glossix_private.profiles where not glossix_private.username_allowed(username) loop
  attempt:=0;loop n:='learner_'||substr(md5(r.user_id::text||':'||attempt::text),1,12);exit when not exists(select 1 from glossix_private.profiles where username=n and user_id<>r.user_id);attempt:=attempt+1;end loop;
  update glossix_private.profiles set username=n where user_id=r.user_id;
 end loop;
 update glossix_private.profiles set display_name=username where display_name<>username;
end$$;
create or replace function glossix_private.profile_presets_guard() returns trigger language plpgsql set search_path='' as $$begin
 if not glossix_private.username_allowed(new.username) then raise exception 'Choose a friendly username without offensive words or swearing';end if;
 if new.region_id is null or not(new.region_id=any(array['','united-kingdom','northern-europe','western-europe','southern-europe','eastern-europe','north-america','central-america-caribbean','south-america','north-africa','sub-saharan-africa','middle-east','central-asia','south-asia','east-asia','southeast-asia','oceania']::text[])) then raise exception 'Choose a listed region';end if;
 if new.hobbies is null or cardinality(new.hobbies)>8 or not(new.hobbies <@ array['Reading','Music','Films','Gaming','Cooking','Baking','Travel','Photography','Art','Drawing','Writing','Crafts','Gardening','Nature','Animals','Walking','Hiking','Running','Cycling','Swimming','Fitness','Football','Basketball','Tennis','Dance','History','Science','Technology','Board games','Languages']::text[]) or cardinality(new.hobbies)<>(select count(distinct x) from unnest(new.hobbies) x) then raise exception 'Choose up to eight different listed hobbies';end if;
 new.username:=lower(trim(new.username));new.display_name:=new.username;return new;
end$$;
drop trigger if exists glossix_profile_presets_guard on glossix_private.profiles;
create trigger glossix_profile_presets_guard before insert or update on glossix_private.profiles for each row execute function glossix_private.profile_presets_guard();
create or replace function public.glossix_profile(p_username text default null,p_display_name text default null,p_global_visible boolean default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();r glossix_private.profiles%rowtype;begin
 if u is null then raise exception 'Please sign in first';end if;
 if p_username is not null then
  if not glossix_private.username_allowed(p_username) then raise exception 'Choose a friendly username using 3–20 letters, numbers or underscores, without offensive words or swearing';end if;
  begin insert into glossix_private.profiles(user_id,username,display_name,global_visible) values(u,lower(trim(p_username)),lower(trim(p_username)),coalesce(p_global_visible,false)) on conflict(user_id) do update set username=excluded.username,display_name=excluded.display_name,global_visible=coalesce(p_global_visible,glossix_private.profiles.global_visible);
  exception when unique_violation then raise exception 'That username is already taken';end;
 end if;
 select * into r from glossix_private.profiles where user_id=u;if not found then return null;end if;
 return jsonb_build_object('user_id',r.user_id,'username',r.username,'display_name',r.username,'global_visible',r.global_visible,'active_languages',r.active_languages,'recent_language',r.recent_language,'avatar_id',r.avatar_id,'region_id',r.region_id,'hobbies',r.hobbies);
end$$;
create or replace function public.glossix_profile_details_set(p_username text,p_region text,p_hobbies text[],p_global_visible boolean) returns jsonb language plpgsql security definer set search_path='' as $$begin
 perform public.glossix_profile(p_username,null,p_global_visible);
 update glossix_private.profiles set region_id=p_region,hobbies=p_hobbies where user_id=auth.uid();return public.glossix_profile();
end$$;
create or replace function public.glossix_profile_view(p_user_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare r glossix_private.profiles%rowtype;score numeric;begin
 if auth.uid() is null then raise exception 'Please sign in first';end if;
 select * into r from glossix_private.profiles where user_id=p_user_id and (user_id=auth.uid() or global_visible or exists(select 1 from glossix_private.friendships f where f.status='accepted' and f.low_id=least(auth.uid(),p_user_id) and f.high_id=greatest(auth.uid(),p_user_id)));
 if not found then raise exception 'This profile is not available';end if;
 select coalesce(sum(points),0) into score from glossix_private.points where user_id=p_user_id;
 return jsonb_build_object('user_id',r.user_id,'username',r.username,'display_name',r.username,'avatar_id',r.avatar_id,'region_id',r.region_id,'hobbies',r.hobbies,'active_languages',r.active_languages,'recent_language',r.recent_language,'points',score::text,'level',public.glossix_level(score));
end$$;
revoke all on function public.glossix_profile_details_set(text,text,text[],boolean),public.glossix_profile_view(uuid) from public,anon,authenticated;
grant execute on function public.glossix_profile_details_set(text,text,text[],boolean),public.glossix_profile_view(uuid) to authenticated;
revoke all on function glossix_private.username_allowed(text),glossix_private.profile_presets_guard() from public,anon,authenticated;
commit;


-- Private preferences only. Preserves accounts, progress and points.
begin;
create table if not exists glossix_private.language_preferences(user_id uuid primary key references auth.users(id) on delete cascade,language text not null check(language in ('en','fr','es','de','pt','it','ru','uk','pl','nl','sv','no','da','fi','cs','sk','hu','ro','bg','el','tr','ar','he','fa','hi','bn','ur','pa','ta','te','zh','ja','ko','vi','th','id','ms','tl','sw','af','ca','eu','cy','ga')));
alter table glossix_private.language_preferences enable row level security;
revoke all on glossix_private.language_preferences from public,anon,authenticated;
create or replace function public.glossix_spoken_language_get() returns jsonb language plpgsql security definer set search_path='' as $$begin if auth.uid() is null then raise exception 'Please sign in';end if;return jsonb_build_object('language',(select language from glossix_private.language_preferences where user_id=auth.uid()));end$$;
create or replace function public.glossix_spoken_language_set(p_language text) returns jsonb language plpgsql security definer set search_path='' as $$begin if auth.uid() is null then raise exception 'Please sign in';end if;if p_language not in ('en','fr','es','de','pt','it','ru','uk','pl','nl','sv','no','da','fi','cs','sk','hu','ro','bg','el','tr','ar','he','fa','hi','bn','ur','pa','ta','te','zh','ja','ko','vi','th','id','ms','tl','sw','af','ca','eu','cy','ga') or p_language is null then raise exception 'Choose a listed language';end if;insert into glossix_private.language_preferences(user_id,language) values(auth.uid(),p_language) on conflict(user_id) do update set language=excluded.language;return jsonb_build_object('language',p_language);end$$;
revoke all on function public.glossix_spoken_language_get(),public.glossix_spoken_language_set(text) from public,anon,authenticated;
grant execute on function public.glossix_spoken_language_get(),public.glossix_spoken_language_set(text) to authenticated;
commit;

-- Profile gradients and free level-earned banners. Run after profile/course setup.
begin;
create table if not exists glossix_private.profile_banners(user_id uuid primary key references auth.users(id) on delete cascade,banner_id text not null default 'classic');
alter table glossix_private.profile_banners enable row level security;
revoke all on glossix_private.profile_banners from public,anon,authenticated;
create or replace function public.glossix_banner_get(p_user_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare b text;begin
 perform public.glossix_profile_view(p_user_id);
 select banner_id into b from glossix_private.profile_banners where user_id=p_user_id;
 return jsonb_build_object('banner_id',coalesce(b,'classic'));
end$$;
create or replace function public.glossix_banner_set(p_banner text) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();required_level integer;account_level numeric;begin
 if u is null then raise exception 'Please sign in first';end if;
 perform public.glossix_profile_view(u);
 select v.minimum into required_level from (values ('classic',1),('black',1),('red',1),('yellow',1),('green',1),('purple',1),('brown',1),('blue',1),('pink',1),('orange',1),('navy',1),('coral',1),('mint',1),('plum',1),('bronze',5),('silver',10),('gold',20),('aurora',35),('sapphire',50),('rose-gold',75),('obsidian',100),('opal',150),('solar',250),('cosmos',500),('legend',1000)) v(id,minimum) where v.id=p_banner;
 if required_level is null then raise exception 'Choose a listed banner';end if;
 select public.glossix_level(coalesce(sum(points),0)) into account_level from glossix_private.points where user_id=u;
 if account_level<required_level then raise exception 'This banner unlocks at level %',required_level;end if;
 insert into glossix_private.profile_banners(user_id,banner_id) values(u,p_banner) on conflict(user_id) do update set banner_id=excluded.banner_id;
 return public.glossix_banner_get(u);
end$$;
revoke all on function public.glossix_banner_get(uuid),public.glossix_banner_set(text) from public,anon,authenticated;
grant execute on function public.glossix_banner_get(uuid),public.glossix_banner_set(text) to authenticated;
commit;

-- Free earned designs and owner grants. Run after SUPABASE-BANNERS.sql.
begin;
create table if not exists glossix_private.cosmetic_catalog(item_id text primary key,minimum_level integer not null check(minimum_level>=1));
insert into glossix_private.cosmetic_catalog values ('banner:classic',1),('banner:black',1),('banner:red',1),('banner:yellow',1),('banner:green',1),('banner:purple',1),('banner:brown',1),('banner:blue',1),('banner:pink',1),('banner:orange',1),('banner:navy',1),('banner:coral',1),('banner:mint',1),('banner:plum',1),('banner:bronze',5),('banner:silver',10),('banner:gold',20),('banner:aurora',35),('banner:sapphire',50),('banner:rose-gold',75),('banner:obsidian',100),('banner:opal',150),('banner:solar',250),('banner:cosmos',500),('banner:legend',1000),('design:plain',1),('design:sage',5),('design:ocean',10),('design:rose',15),('design:sand',25),('design:lavender',35),('design:copper',50),('design:silver',75),('design:gold',100),('design:night',150),('design:forest',250),('design:cosmic',500),('design:legend',1000) on conflict(item_id) do update set minimum_level=excluded.minimum_level;
create table if not exists glossix_private.cosmetic_grants(user_id uuid references auth.users(id) on delete cascade,item_id text references glossix_private.cosmetic_catalog(item_id),granted_at timestamptz not null default now(),primary key(user_id,item_id));
create table if not exists glossix_private.profile_designs(user_id uuid primary key references auth.users(id) on delete cascade,design_id text not null default 'plain');
alter table glossix_private.cosmetic_catalog enable row level security;
alter table glossix_private.cosmetic_grants enable row level security;
alter table glossix_private.profile_designs enable row level security;
revoke all on glossix_private.cosmetic_catalog,glossix_private.cosmetic_grants,glossix_private.profile_designs from public,anon,authenticated;
create or replace function public.glossix_cosmetics_get(p_user_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare b jsonb;d text;g jsonb;begin
 b:=public.glossix_banner_get(p_user_id);
 select design_id into d from glossix_private.profile_designs where user_id=p_user_id;
 if p_user_id=auth.uid() then select coalesce(jsonb_agg(item_id),'[]'::jsonb) into g from glossix_private.cosmetic_grants where user_id=p_user_id;else g:='[]'::jsonb;end if;
 return b||jsonb_build_object('design_id',coalesce(d,'plain'),'granted_items',g);end$$;
create or replace function glossix_private.cosmetic_allowed(p_user uuid,p_item text) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from glossix_private.cosmetic_catalog c where c.item_id=p_item and (public.glossix_level((select coalesce(sum(points),0) from glossix_private.points where user_id=p_user))::numeric>=c.minimum_level or exists(select 1 from glossix_private.cosmetic_grants g where g.user_id=p_user and g.item_id=p_item)));
$$;
create or replace function public.glossix_banner_set(p_banner text) returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();begin
 if u is null then raise exception 'Please sign in first';end if;perform public.glossix_profile_view(u);
 if not glossix_private.cosmetic_allowed(u,'banner:'||p_banner) then raise exception 'This banner is locked or unavailable';end if;
 insert into glossix_private.profile_banners(user_id,banner_id) values(u,p_banner) on conflict(user_id) do update set banner_id=excluded.banner_id;return public.glossix_cosmetics_get(u);end$$;
create or replace function public.glossix_design_set(p_design text) returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();begin
 if u is null then raise exception 'Please sign in first';end if;perform public.glossix_profile_view(u);
 if not glossix_private.cosmetic_allowed(u,'design:'||p_design) then raise exception 'This design is locked or unavailable';end if;
 insert into glossix_private.profile_designs(user_id,design_id) values(u,p_design) on conflict(user_id) do update set design_id=excluded.design_id;return public.glossix_cosmetics_get(u);end$$;
-- Owner-only: use SQL Editor, never grant this function to app roles.
create or replace function glossix_private.cosmetic_grant(p_username text,p_item text) returns void language plpgsql security definer set search_path='' as $$declare u uuid;begin
 select user_id into u from glossix_private.profiles where username=lower(trim(p_username));if u is null then raise exception 'Username not found';end if;
 if not exists(select 1 from glossix_private.cosmetic_catalog where item_id=p_item) then raise exception 'Unknown reward';end if;
 insert into glossix_private.cosmetic_grants(user_id,item_id) values(u,p_item) on conflict do nothing;end$$;
revoke all on function glossix_private.cosmetic_allowed(uuid,text),glossix_private.cosmetic_grant(text,text) from public,anon,authenticated;
revoke all on function public.glossix_cosmetics_get(uuid),public.glossix_banner_set(text),public.glossix_design_set(text) from public,anon,authenticated;
grant execute on function public.glossix_cosmetics_get(uuid),public.glossix_banner_set(text),public.glossix_design_set(text) to authenticated;
commit;

